{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case field")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid case field type")
    if not nodes:
        raise ValueError("tree must contain a root")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")

    required = set(required_symbols)
    by_id = {}
    ordered_nodes = []
    node_fields = ("id", "parent", "symbol", "depth", "removable", "utility")

    for node in nodes:
        if not isinstance(node, dict) or any(field not in node for field in node_fields):
            raise ValueError("invalid node")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or not isinstance(symbol, str):
            raise ValueError("node identifiers and symbols must be strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("node parent must be a string or null")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("node depth must be a nonnegative integer")
        if not isinstance(removable, bool):
            raise ValueError("node removable flag must be boolean")
        if (isinstance(utility, bool) or not isinstance(utility, (int, float))
                or not math.isfinite(utility)):
            raise ValueError("node utility must be finite numeric")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        by_id[node_id] = node
        ordered_nodes.append(node)

    roots = [node for node in ordered_nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]["id"]
    if roots[0]["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node_id: [] for node_id in by_id}
    for node in ordered_nodes:
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("node parent is absent")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("inconsistent node depth")
        children[parent].append(node["id"])

    represented = {symbol: 0 for symbol in required}
    for node in ordered_nodes:
        symbol = node["symbol"]
        if symbol in represented:
            represented[symbol] += 1
    if any(count == 0 for count in represented.values()):
        raise ValueError("required symbol is not represented")

    retained = set(by_id)
    removed = []
    candidates = sorted(ordered_nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        symbol = node["symbol"]
        if node_id == root_id or not node["removable"] or symbol in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        if symbol in represented and represented[symbol] <= 1:
            continue
        retained.remove(node_id)
        removed.append(node_id)
        if symbol in represented:
            represented[symbol] -= 1

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
